--
-- Name: get_analysis(character varying, public.analysis_state[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analysis(studyid character varying, analysisstate public.analysis_state[], pagelimit integer, pageoffset integer) RETURNS TABLE(id character varying, study_id character varying, type public.analysis_type, state public.analysis_state, analysis_schema_id integer, analysis_data_id integer, created_at timestamp without time zone, updated_at timestamp without time zone, file_id character varying, file_analysis_id character varying, file_study_id character varying, name text, size bigint, md5 character, access public.access_type, file_type text, data_type character varying, info json)
    LANGUAGE plpgsql
    AS $$
	BEGIN
		RETURN QUERY
			SELECT *
			FROM (
				SELECT	analysis.id,
								analysis.study_id,
								analysis.type,
								analysis.state,
								analysis.analysis_schema_id,
								analysis.analysis_data_id,
								analysis.created_at,
								analysis.updated_at
				FROM analysis
				WHERE analysis.study_id = studyId AND analysis.state = ANY (analysisState)
				ORDER BY analysis.id ASC
				LIMIT pageLimit OFFSET pageOffset
			) AS filtered_analysis
			JOIN (
				SELECT 	filtered_file.id					AS file_id,
								filtered_file.analysis_id	AS file_analysis_id,
								filtered_file.study_id		AS file_study_id,
								filtered_file.name,
								filtered_file.size,
								filtered_file.md5,
								filtered_file.access,
								filtered_file.type				AS file_type,
								filtered_file.data_type,
								info.info
				FROM (
					SELECT * FROM file WHERE file.study_id = studyId
				) AS filtered_file
				JOIN info 
				ON filtered_file.id = info.id AND info.id_type = 'File'
			)
			AS file_info
			ON filtered_analysis.id = file_info.file_analysis_id;

	END;
$$;


--
-- Name: get_analysis_data(character varying, public.analysis_state[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analysis_data(studyid character varying, analysisstate public.analysis_state[], pagelimit integer, pageoffset integer) RETURNS TABLE(id character varying, analysis_data_id integer, study_id character varying, state public.analysis_state, data_id bigint, data jsonb)
    LANGUAGE plpgsql
    AS $$
begin
  return query

  SELECT *
  FROM (    SELECT
              analysis.id,
              analysis.analysis_data_id,
              analysis.study_id,
              analysis.state
            FROM analysis
            WHERE analysis.study_id = studyId AND analysis.state = any(analysisState)
            ORDER BY analysis.id  ASC
            LIMIT pageLimit
            OFFSET pageOffset) AS filtered_analysis
        LEFT JOIN
          ( SELECT
            analysis_data.id               AS data_id,
            analysis_data.data
            FROM analysis_data ) AS analysisData
        ON filtered_analysis.analysis_data_id = analysisData.data_id
        ORDER BY filtered_analysis.id  ASC;

end;

$$;


--
-- Name: get_analysis_schema(character varying, public.analysis_state[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analysis_schema(studyid character varying, analysisstate public.analysis_state[], pagelimit integer, pageoffset integer) RETURNS TABLE(id character varying, analysis_schema_id integer, study_id character varying, state public.analysis_state, schema_id bigint, version integer, name character varying, schema jsonb, options jsonb, analysis_schema_created_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
begin
  return query

  SELECT *
  FROM ( SELECT
          analysis.id,
          analysis.analysis_schema_id,
          analysis.study_id,
          analysis.state
        FROM analysis
        WHERE analysis.study_id = studyId AND analysis.state = any(analysisState)
        ORDER BY analysis.id  ASC
        LIMIT pageLimit
        OFFSET pageOffset) AS filtered_analysis
  LEFT JOIN
      ( SELECT
            analysis_schema.id               AS schema_id,
            analysis_schema.version,
            analysis_schema.name,
            analysis_schema.schema,
            analysis_schema.options,
            analysis_schema.created_at       AS analysis_schema_created_at
        FROM analysis_schema) AS schema
  ON filtered_analysis.analysis_schema_id = schema.schema_id
  ORDER BY filtered_analysis.id  ASC;

end;

$$;


--
-- Name: get_analysis_state_change(character varying, public.analysis_state[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analysis_state_change(studyid character varying, analysisstate public.analysis_state[], pagelimit integer, pageoffset integer) RETURNS TABLE(id character varying, study_id character varying, type public.analysis_type, state public.analysis_state, analysis_schema_id integer, analysis_data_id integer, created_at timestamp without time zone, updated_at timestamp without time zone, analysis_state_change_id bigint, analysis_id character varying, initial_state public.analysis_state, updated_state public.analysis_state, state_updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	begin
	return query

	SELECT *
	FROM    ( SELECT * FROM analysis
     		 WHERE analysis.study_id = studyId AND analysis.state =  ANY(analysisState)
		     ORDER BY analysis.id  ASC
			 LIMIT pageLimit
		     OFFSET pageOffset) AS filtered_analysis
	LEFT JOIN ( SELECT
					analysis_state_change.id               AS analysis_state_change_id,
					analysis_state_change.analysis_id,
					analysis_state_change.initial_state,
					analysis_state_change.updated_state,
					analysis_state_change.updated_at       AS state_updated_at
		        FROM analysis_state_change
				ORDER BY analysis_state_change.analysis_id ASC ) AS history
	ON filtered_analysis.id = history.analysis_id;

end;

$$;


